Method.Source:
/// <summary>
/// Finds a data setup line.
/// </summary>
public static OLK_EnvironmentDataSetupTrans find(
    OLK_EdsEnvironmentId        _environmentId,
    OLK_EdsDataAreaId           _dataAreaId,
    OLK_EdsRefTableId           _refTableId,
    OLK_EdsRefRecId             _refRecId,
    OLK_EdsFieldId              _fieldId,
    OLK_EdsEncryptedMethodName  _encryptedMethodName = '',
    boolean                     _forUpdate = false)
{
    OLK_EnvironmentDataSetupTrans trans;

    trans.selectForUpdate(_forUpdate);

    select firstonly trans
        where trans.EnvironmentId       == _environmentId
           && trans.RefDataAreaId       == _dataAreaId
           && trans.RefTableId          == _refTableId
           && trans.RefRecId            == _refRecId
           && trans.FieldId             == _fieldId
           && trans.EncryptedMethodName == _encryptedMethodName;

    return trans;
}

/// <summary>
/// Returns the AOT name of the referenced table.
/// </summary>
[SysClientCacheDataMethodAttribute(true)]
public display TableName tableName()
{
    return this.RefTableId ? tableId2Name(this.RefTableId) : '';
}

/// <summary>
/// Returns the label of the referenced table.
/// </summary>
[SysClientCacheDataMethodAttribute(true)]
public display Name tableLabel()
{
    return this.RefTableId ? tableId2PName(this.RefTableId) : '';
}

/// <summary>
/// Returns the AOT name of the referenced field, or the edit method of an encrypted line that has one.
/// </summary>
[SysClientCacheDataMethodAttribute(true)]
public display FieldName fieldName()
{
    if (this.EncryptedMethodName)
    {
        return this.EncryptedMethodName;
    }

    return (this.RefTableId && this.FieldId) ? fieldId2Name(this.RefTableId, this.FieldId) : '';
}

/// <summary>
/// Returns the label of the referenced field.
/// </summary>
[SysClientCacheDataMethodAttribute(true)]
public display Name fieldLabel()
{
    return this.FieldId ? fieldId2PName(this.RefTableId, this.FieldId) : '';
}

/// <summary>
/// Returns the label of the enum value for enum fields.
/// </summary>
public display Name enumValueLabel()
{
    DictField dictField = this.FieldId ? new DictField(this.RefTableId, this.FieldId) : null;

    if (dictField && dictField.baseType() == Types::Enum && strLen(this.Value))
    {
        return new DictEnum(dictField.enumId()).value2Label(str2Int(this.Value));
    }

    return '';
}

/// <summary>
/// Gets or sets the referenced table by its AOT name.
/// </summary>
/// <param name = "_set">true when the value is set.</param>
/// <param name = "_name">The table name.</param>
/// <returns>The AOT name of the referenced table.</returns>
public edit TableName dataTableName(boolean _set, TableName _name)
{
    if (_set)
    {
        TableId tableId = _name ? tableName2Id(_name) : 0;

        if (_name && !tableId)
        {
            checkFailed(strFmt("@OLK_EDSLabel:TableNotFound", _name));
        }
        else if (tableId != this.RefTableId)
        {
            this.clearCipherText();
            this.RefTableId          = tableId;
            this.FieldId             = 0;
            this.EncryptedMethodName = '';
            this.initRefDataAreaId();
        }
    }

    return this.tableName();
}

/// <summary>
/// Gets or sets the referenced field by its AOT name. On an encrypted line the name can also be an edit method of the table.
/// </summary>
/// <param name = "_set">true when the value is set.</param>
/// <param name = "_name">The field name, or the edit method name on an encrypted line.</param>
/// <returns>The AOT name of the referenced field or edit method.</returns>
public edit FieldName dataFieldName(boolean _set, FieldName _name)
{
    if (_set)
    {
        FieldId fieldId = (_name && this.RefTableId) ? fieldName2Id(this.RefTableId, _name) : 0;

        if (this.EncryptedField)
        {
            if (fieldId != this.FieldId || (fieldId ? '' : _name) != this.EncryptedMethodName)
            {
                this.clearCipherText();
            }

            this.FieldId             = fieldId;
            this.EncryptedMethodName = fieldId ? '' : _name;
        }
        else
        {
            if (_name && !fieldId)
            {
                checkFailed(strFmt("@OLK_EDSLabel:FieldNotFound", _name, this.tableName()));
            }
            else
            {
                this.FieldId = fieldId;
            }
        }
    }

    return this.fieldName();
}

/// <summary>
/// Gets or sets the value written to the field. Values of encrypted fields are encrypted with the key of the line's
/// environment as they are entered, only the cipher text is stored, and the form shows a mask.
/// </summary>
/// <param name = "_set">true when the value is set.</param>
/// <param name = "_value">The value.</param>
/// <returns>The value, or a mask for encrypted fields.</returns>
public edit OLK_EdsValue editValue(boolean _set, OLK_EdsValue _value)
{
    if (_set)
    {
        if (this.EncryptedField)
        {
            this.setEncryptedValue(_value);
        }
        else
        {
            this.Value = this.normalizeValue(_value);
        }
    }

    if (this.EncryptedField && (this.Value || this.CipherText))
    {
        return OLK_EnvironmentDataSetupCrypto::ValueMask;
    }

    return this.Value;
}

/// <summary>
/// Encrypts a value with the public key of the line's environment and stores only the cipher text.
/// </summary>
/// <param name = "_value">The value; the mask leaves the stored value as it is, an empty value clears it.</param>
public void setEncryptedValue(str _value)
{
    OLK_EnvironmentDataSetupTable environment;

    if (_value == OLK_EnvironmentDataSetupCrypto::ValueMask)
    {
        return;
    }

    if (!_value)
    {
        this.Value      = '';
        this.CipherText = '';
        return;
    }

    if (!this.isValidValue(_value))
    {
        throw error(strFmt("@OLK_EDSLabel:EncryptedValueInvalid", this.fieldName()));
    }

    environment = OLK_EnvironmentDataSetupTable::find(this.EnvironmentId);

    if (!environment.PublicKey)
    {
        throw error(strFmt("@OLK_EDSLabel:EnvironmentNotEnrolled", this.EnvironmentId));
    }

    this.CipherText = OLK_EnvironmentDataSetupCrypto::encrypt(environment.PublicKey, this.normalizeValue(_value), this.encryptionBinding());
    this.Value      = '';
}

/// <summary>
/// Checks a value against the type of the referenced field. An encrypted value cannot be checked after it is encrypted, so
/// this is done first. A value for an edit method is not checked, because the method decides what it accepts.
/// </summary>
private boolean isValidValue(str _value)
{
    DictField dictField = this.referencedDictField();

    return this.EncryptedMethodName || !dictField || OLK_EnvironmentDataSetupValueConverter::isValid(this.normalizeValue(_value), dictField);
}

/// <summary>
/// The text an encrypted value is bound to: environment, company, table, edit method or field, and record. A cipher text
/// cannot be decrypted for a line where any of these differ.
/// </summary>
public str encryptionBinding()
{
    str target = this.EncryptedMethodName;

    if (!target && this.RefTableId && this.FieldId)
    {
        target = 'field:' + fieldId2Name(this.RefTableId, this.FieldId);
    }

    return strLwr(strFmt('%1|%2|%3|%4|%5',
        this.EnvironmentId,
        this.RefDataAreaId,
        this.RefTableId ? tableId2Name(this.RefTableId) : '',
        target,
        int642Str(this.RefRecId)));
}

/// <summary>
/// Clears the encrypted value when the line is moved to another environment, company, table, method or record, because it
/// could not be decrypted there.
/// </summary>
private void clearCipherText()
{
    if (this.CipherText)
    {
        this.CipherText = '';
        warning("@OLK_EDSLabel:EncryptedValueCleared");
    }
}

/// <summary>
/// Stores enum values that are entered as a symbol or label as their integer value.
/// </summary>
private OLK_EdsValue normalizeValue(OLK_EdsValue _value)
{
    DictField dictField = this.referencedDictField();

    if (dictField && dictField.baseType() == Types::Enum && _value)
    {
        DictEnum    dictEnum = new DictEnum(dictField.enumId());
        str         value    = strLTrim(strRTrim(_value));
        int         enumValue;

        if (value == int2Str(str2Int(value)))
        {
            return value;
        }

        enumValue = dictEnum.symbol2Value(value);

        if (enumValue == 255)
        {
            // Not a symbol, so try the label.
            for (int i = 0; i < dictEnum.values(); i++)
            {
                if (dictEnum.index2Label(i) == value)
                {
                    return int2Str(dictEnum.index2Value(i));
                }
            }

            return _value;
        }

        return int2Str(enumValue);
    }

    return _value;
}

/// <summary>
/// The referenced field; null when no field is selected.
/// </summary>
public DictField referencedDictField()
{
    if (!this.RefTableId || !this.FieldId)
    {
        return null;
    }

    return new DictField(this.RefTableId, this.FieldId);
}

/// <summary>
/// Checks whether the referenced field is an enum field.
/// </summary>
public boolean isEnumField()
{
    DictField dictField = this.referencedDictField();

    return dictField && dictField.baseType() == Types::Enum;
}

/// <summary>
/// Sets the company for company specific tables and clears it for shared tables.
/// </summary>
private void initRefDataAreaId()
{
    DictTable dictTable = this.RefTableId ? new DictTable(this.RefTableId) : null;

    if (dictTable && dictTable.dataPrCompany())
    {
        if (!this.RefDataAreaId)
        {
            this.RefDataAreaId = curExt();
        }
    }
    else
    {
        this.RefDataAreaId = '';
    }
}

/// <summary>
/// Looks up the fields of the referenced table.
/// </summary>
/// <param name = "_control">The control that shows the field name.</param>
public void lookupDataFieldName(FormStringControl _control)
{
    SysTableLookup      sysTableLookup;
    TmpSysTableField    tmpSysTableField;
    Query               query = new Query();

    if (!this.RefTableId)
    {
        return;
    }

    TmpSysTableField::findTableFields(tmpSysTableField, this.RefTableId);

    query.addDataSource(tableNum(TmpSysTableField));

    sysTableLookup = SysTableLookup::newParameters(tableNum(TmpSysTableField), _control);
    sysTableLookup.addLookupfield(fieldNum(TmpSysTableField, FieldName), true);
    sysTableLookup.addLookupfield(fieldNum(TmpSysTableField, FieldLabel));
    sysTableLookup.parmQuery(query);
    sysTableLookup.parmTmpBuffer(tmpSysTableField);
    sysTableLookup.performFormLookup();
}

public void modifiedField(FieldId _fieldId)
{
    super(_fieldId);

    switch (_fieldId)
    {
        case fieldNum(OLK_EnvironmentDataSetupTrans, EncryptedField):
            this.EncryptedMethodName = '';

            if (this.EncryptedField)
            {
                // The line keeps its field, and a plain value becomes cipher text straight away.
                this.setEncryptedValue(this.Value);
            }
            else
            {
                // This environment cannot decrypt the value, so it must be entered again.
                this.Value = '';
                this.clearCipherText();
            }
            break;

        case fieldNum(OLK_EnvironmentDataSetupTrans, EncryptedMethodName):
            if (this.EncryptedMethodName)
            {
                this.FieldId = 0;
            }
            this.clearCipherText();
            break;

        case fieldNum(OLK_EnvironmentDataSetupTrans, FieldId):
            this.clearCipherText();
            break;

        case fieldNum(OLK_EnvironmentDataSetupTrans, RefTableId):
            this.FieldId             = 0;
            this.EncryptedMethodName = '';
            this.initRefDataAreaId();
            this.clearCipherText();
            break;

        case fieldNum(OLK_EnvironmentDataSetupTrans, EnvironmentId):
        case fieldNum(OLK_EnvironmentDataSetupTrans, RefDataAreaId):
        case fieldNum(OLK_EnvironmentDataSetupTrans, RefRecId):
            this.clearCipherText();
            break;
    }
}

/// <summary>
/// Refuses to mark a line as encrypted when its value could not be encrypted, so that a plain value is never left on an
/// encrypted line.
/// </summary>
public boolean validateField(FieldId _fieldIdToCheck)
{
    boolean ret = super(_fieldIdToCheck);

    if (ret && _fieldIdToCheck == fieldNum(OLK_EnvironmentDataSetupTrans, EncryptedField) && this.EncryptedField)
    {
        if (!OLK_EnvironmentDataSetupTable::find(this.EnvironmentId).PublicKey)
        {
            ret = checkFailed(strFmt("@OLK_EDSLabel:EnvironmentNotEnrolled", this.EnvironmentId));
        }
        else if (this.Value && !this.isValidValue(this.Value))
        {
            ret = checkFailed(strFmt("@OLK_EDSLabel:EncryptedValueInvalid", this.fieldName()));
        }
    }

    return ret;
}

public boolean validateWrite()
{
    boolean     ret = super();
    DictTable   dictTable = this.RefTableId ? new DictTable(this.RefTableId) : null;

    if (ret && !dictTable)
    {
        ret = checkFailed(strFmt("@OLK_EDSLabel:TableNotFound", this.RefTableId));
    }

    if (ret)
    {
        if (this.EncryptedMethodName)
        {
            if (!tableHasMethod(dictTable, this.EncryptedMethodName))
            {
                ret = checkFailed(strFmt("@OLK_EDSLabel:FieldNotFound", this.EncryptedMethodName, dictTable.name()));
            }
        }
        else if (this.EncryptedField && !this.FieldId)
        {
            ret = checkFailed("@OLK_EDSLabel:EncryptedFieldOrMethodEmpty");
        }
        else if (!this.referencedDictField())
        {
            ret = checkFailed(strFmt("@OLK_EDSLabel:FieldNotFound", this.FieldId, dictTable.name()));
        }
    }

    if (ret && dictTable.dataPrCompany() && !this.RefDataAreaId)
    {
        ret = checkFailed("@OLK_EDSLabel:CompanyEmpty");
    }

    if (ret && this.EncryptedField && this.Value && (this.Value != this.orig().Value || !this.orig().EncryptedField))
    {
        // Encrypted values are stored as cipher text only; a plain value can arrive only by import or code.
        ret = checkFailed("@OLK_EDSLabel:EncryptedValueNotEncrypted");
    }

    if (ret && !this.referencedRecordExists())
    {
        ret = checkFailed(strFmt("@OLK_EDSLabel:RecordNotFound", dictTable.name(), this.RefRecId));
    }

    return ret;
}

/// <summary>
/// Checks that the referenced record exists in the company of the line.
/// </summary>
public boolean referencedRecordExists()
{
    boolean found;

    if (!this.RefRecId)
    {
        return false;
    }

    changecompany(this.RefDataAreaId ? this.RefDataAreaId : curExt())
    {
        found = this.findReferencedRecord().RecId != 0;
    }

    return found;
}

/// <summary>
/// Selects the record that this line updates, in the current company.
/// </summary>
/// <param name = "_forUpdate">true if the record is selected for update.</param>
/// <returns>The referenced record; an empty buffer if it does not exist.</returns>
public Common findReferencedRecord(boolean _forUpdate = false)
{
    DictTable   dictTable = new DictTable(this.RefTableId);
    Common      record;

    if (dictTable)
    {
        record = dictTable.makeRecord();
        record.selectForUpdate(_forUpdate);

        select firstonly record
            where record.RecId == this.RefRecId;
    }

    return record;
}

/// <summary>
/// Adds a field of a record to the data setup of an environment.
/// </summary>
/// <param name = "_record">The record that holds the field.</param>
/// <param name = "_fieldId">The field to add; 0 when an edit method is used.</param>
/// <param name = "_environmentId">The environment.</param>
/// <param name = "_overwriteType">How an existing line for the same field is handled.</param>
/// <param name = "_description">Description of the line.</param>
/// <param name = "_encryptedMethodName">Edit method for encrypted fields.</param>
/// <returns>The created or updated line; an empty buffer if nothing was written.</returns>
public static OLK_EnvironmentDataSetupTrans createTrans(
    Common                      _record,
    FieldId                     _fieldId,
    OLK_EdsEnvironmentId        _environmentId,
    OLK_EdsOverwriteType        _overwriteType,
    Description                 _description,
    OLK_EdsEncryptedMethodName  _encryptedMethodName = '')
{
    DictTable           dictTable = new DictTable(_record.TableId);
    OLK_EdsDataAreaId   dataAreaId = dictTable.dataPrCompany() ? _record.DataAreaId : '';
    FieldName           fieldName = _fieldId ? fieldId2Name(_record.TableId, _fieldId) : _encryptedMethodName;
    OLK_EnvironmentDataSetupTrans trans;

    if (!OLK_EnvironmentDataSetupTable::exist(_environmentId))
    {
        throw error(strFmt("@OLK_EDSLabel:EnvironmentNotFound", _environmentId));
    }

    ttsbegin;

    trans = OLK_EnvironmentDataSetupTrans::find(_environmentId, dataAreaId, _record.TableId, _record.RecId, _fieldId, _encryptedMethodName, true);

    if (trans.RecId)
    {
        if (_overwriteType == OLK_EdsOverwriteType::Never)
        {
            throw error(strFmt("@OLK_EDSLabel:TransExists", fieldName, _environmentId));
        }

        if (_overwriteType == OLK_EdsOverwriteType::IfNotExists)
        {
            warning(strFmt("@OLK_EDSLabel:TransExists", fieldName, _environmentId));
            ttscommit;
            return trans;
        }
    }

    // A line that was marked as encrypted stays encrypted when it is overwritten.
    boolean keepEncrypted = trans.RecId && trans.EncryptedField;

    trans.EnvironmentId         = _environmentId;
    trans.RefDataAreaId         = dataAreaId;
    trans.RefTableId            = _record.TableId;
    trans.RefRecId              = _record.RecId;
    trans.FieldId               = _fieldId;
    trans.EncryptedMethodName   = _encryptedMethodName;
    trans.EncryptedField        = (keepEncrypted || !_fieldId) ? NoYes::Yes : NoYes::No;
    trans.Description           = _description ? _description : (_fieldId ? fieldId2PName(_record.TableId, _fieldId) : _encryptedMethodName);

    if (_fieldId)
    {
        str value = OLK_EnvironmentDataSetupValueConverter::toStr(_record.(_fieldId), new DictField(_record.TableId, _fieldId));

        if (keepEncrypted)
        {
            trans.setEncryptedValue(value);
        }
        else
        {
            trans.Value = value;
        }
    }

    trans.write();

    ttscommit;

    info(strFmt("@OLK_EDSLabel:TransCreated", fieldName, _environmentId));

    return trans;
}

/// <summary>
/// Adds the field behind a form control, with the value of the current record, to the data setup of an environment.
/// </summary>
/// <param name = "_control">A control bound to a table field or an edit method.</param>
/// <param name = "_environmentId">The environment.</param>
/// <param name = "_description">Description of the line.</param>
public static void createFromControl(FormControl _control, OLK_EdsEnvironmentId _environmentId, Description _description)
{
    FormDataSource  dataSource;
    FieldBinding    binding;
    Object          controlObject = _control;
    str             dataMethod;

    if (!_environmentId)
    {
        throw error("@OLK_EDSLabel:EnvironmentIdEmpty");
    }

    dataSource = _control ? _control.dataSourceObject() : null;

    if (!dataSource || !dataSource.cursor().RecId)
    {
        throw error("@OLK_EDSLabel:FieldRefNotFound");
    }

    binding = _control.fieldBinding();

    if (binding && !binding.isNull() && binding.fieldId())
    {
        OLK_EnvironmentDataSetupTrans::createTrans(dataSource.cursor(), binding.fieldId(), _environmentId, OLK_EdsOverwriteType::Always, _description);
        return;
    }

    // Encrypted fields are shown through edit methods, so only the method name is known.
    if (Form::formKernelObjectHasMethod(_control, identifierStr(dataMethod)))
    {
        dataMethod = controlObject.dataMethod();
    }

    if (!dataMethod)
    {
        throw error("@OLK_EDSLabel:FieldRefNotFound");
    }

    OLK_EnvironmentDataSetupTrans::createTrans(dataSource.cursor(), 0, _environmentId, OLK_EdsOverwriteType::Always, _description, dataMethod);
}
